import test from 'node:test';
import assert from 'node:assert/strict';
import { ART_ASSETS, REFERENCE_ASSETS, referenceArtPlan, roomArtKeys, parallaxOffsets, svgDataUri } from '../src/jam2d/visual/art.js';
import { ensureAnimations } from '../src/jam2d/visual/animations.js';

test('Extracted SVG uses Phaser-compatible base64 with UTF-8 preserved', () => {
  const source = '<svg xmlns="http://www.w3.org/2000/svg"><!-- Каракурт --></svg>';
  const uri = svgDataUri(source);
  assert.ok(uri.startsWith('data:image/svg+xml;base64,'));
  const decoded = Uint8Array.from(atob(uri.split(',')[1]), char => char.charCodeAt(0));
  assert.equal(new TextDecoder().decode(decoded), source);
});

function artScene() {
  const textures = new Map(), animations = new Map();
  for (const key of ['art2d-karakurt-body', 'art2d-human-slipper']) {
    textures.set(key, { getSourceImage: () => ({ art: key }) });
  }
  return {
    texturesByKey: textures,
    textures: {
      exists: key => textures.has(key),
      get: key => textures.get(key),
      createCanvas(key) {
        const calls = [];
        const context = new Proxy({}, {
          get: (_, name) => (...args) => calls.push([name, ...args]),
          set: () => true,
        });
        const texture = { context, calls, add() {}, refresh() {} };
        textures.set(key, texture);
        return texture;
      },
    },
    anims: {
      exists: key => animations.has(key),
      create: config => animations.set(config.key, config),
      generateFrameNumbers: (key, { start, end }) => Array.from({ length: end - start + 1 }, (_, i) => ({ key, frame: start + i })),
    },
  };
}

test('Art manifest uses eight local SVGs and contracted dimensions', () => {
  assert.equal(ART_ASSETS.length, 8);
  assert.equal(new Set(ART_ASSETS.map(asset => asset.key)).size, 8);
  for (const asset of ART_ASSETS) {
    assert.match(asset.file, /^[a-z-]+\.svg$/);
    const expected = asset.file.includes('room-') || asset.file.includes('kitchen-') || asset.file === 'moonlit-encounter.svg' ? [1600, 900]
      : asset.file === 'human-slipper.svg' ? [384, 768] : [256, 256];
    assert.deepEqual([asset.width, asset.height], expected);
  }
  assert.deepEqual(roomArtKeys('Kitchen'), ['art2d-kitchen-far', 'art2d-kitchen-near']);
  assert.deepEqual(roomArtKeys('LivingRoom'), ['art2d-living-room-far', 'art2d-living-room-near']);
  assert.equal(roomArtKeys('Bathroom'), null, 'other rooms retain existing presentation');
});

test('Both room layers respond to player motion with different bounded speeds', () => {
  assert.deepEqual(parallaxOffsets(960), { far: -0, near: -0 });
  const left = parallaxOffsets(0), right = parallaxOffsets(1920);
  assert.ok(Math.abs(right.near) > Math.abs(right.far));
  assert.equal(left.near, -right.near);
  assert.equal(left.far, -right.far);
  assert.deepEqual(parallaxOffsets(99999), right);
});

test('SVG art is composed into every gait frame without removing eight procedural legs', () => {
  const scene = artScene();
  ensureAnimations(scene);
  for (const state of ['idle', 'walk', 'turn_left', 'turn_right', 'jump', 'web']) {
    const { calls } = scene.texturesByKey.get(`jam-fallback-spider-${state}`);
    assert.equal(calls.filter(([name]) => name === 'drawImage').length, 8);
    // Two strokes for each of eight jointed legs; web adds its own stroke.
    assert.ok(calls.filter(([name]) => name === 'stroke').length >= 8 * 8 * 2);
    const bodyPositions = calls.filter(([name]) => name === 'drawImage').map(call => call[7]);
    assert.ok(new Set(bodyPositions).size > 1, `${state}: SVG body follows procedural motion`);
  }
  for (const state of ['idle', 'walk', 'run', 'attack', 'collision', 'fall']) {
    const { calls } = scene.texturesByKey.get(`jam-fallback-human-${state}`);
    assert.equal(calls.filter(([name]) => name === 'drawImage').length, 8);
    const poses = calls.filter(([name]) => name === 'translate' || name === 'rotate');
    assert.ok(new Set(poses.map(JSON.stringify)).size > 2, `${state}: leg art is animated`);
  }
});

